"""Date-window membership for the date_window fixture."""

from __future__ import annotations

from datetime import datetime


def _parse_and_validate_date(date_str: str) -> datetime:
    """Parse and validate a date string in ISO format (YYYY-MM-DD).

    Raises ValueError if the date is malformed or invalid.
    """
    if not isinstance(date_str, str):
        raise ValueError(f"Date must be a string, got {type(date_str)}")

    # Check format: must be exactly YYYY-MM-DD with proper zero-padding
    if len(date_str) != 10:
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    try:
        year_str, month_str, day_str = date_str.split('-')
        year = int(year_str)
        month = int(month_str)
        day = int(day_str)
    except ValueError:
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    # Check for zero-padding: year must be 4 digits, month and day must be 2 digits
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError(f"Date must be in YYYY-MM-DD format with zero-padding, got {date_str}")

    # Validate the date using datetime (this checks leap years, valid months, etc.)
    try:
        return datetime(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid date: {date_str}") from e


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    A target date falls inside a window if it is >= start and <= end (inclusive).
    All dates must be in strict ISO calendar-date form (YYYY-MM-DD).
    Windows may be in any order. All dates and windows are validated.
    """
    # Parse and validate the target date
    target = _parse_and_validate_date(target_date)

    # Parse and validate all window endpoints first, and check start <= end
    parsed_windows = []
    for start_str, end_str in windows:
        start = _parse_and_validate_date(start_str)
        end = _parse_and_validate_date(end_str)

        # Check that start <= end
        if start > end:
            raise ValueError(f"Window start {start_str} is after end {end_str}")

        parsed_windows.append((start, end))

    # Check if target falls in any window (inclusive boundaries)
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False
